<style>
  :root {
    --gold: #C5A44E;
    --gold-light: #E8D48B;
    --gold-dark: #A68832;
    --bg-dark: #1A1A2E;
    --bg-card: #16213E;
    --bg-section: #0F3460;
    --text-primary: #E8E8E8;
    --text-secondary: #B0B0C8;
    --accent-blue: #4A90D9;
    --accent-red: #E74C3C;
    --accent-green: #2ECC71;
    --accent-purple: #9B59B6;
    --border: rgba(197,164,78,0.25);
  }

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    font-family: 'Segoe UI', 'Helvetica Neue', Arial, sans-serif;
    background: var(--bg-dark);
    color: var(--text-primary);
    line-height: 1.7;
    font-size: 15px;
  }

  .container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 24px;
  }

  /* Hero Header */
  .hero {
    background: linear-gradient(135deg, #1A1A2E 0%, #16213E 40%, #0F3460 100%);
    border-bottom: 3px solid var(--gold);
    padding: 64px 0 48px;
    text-align: center;
