  .hero h1 {
    font-size: 2.6rem;
    font-weight: 700;
    color: var(--gold);
    letter-spacing: -0.5px;
    margin-bottom: 12px;
    text-shadow: 0 2px 12px rgba(197,164,78,0.3);
  }
  .hero .subtitle {
    font-size: 1.15rem;
    color: var(--text-secondary);
    max-width: 720px;
    margin: 0 auto;
  }
  .hero .meta {
    margin-top: 20px;
    font-size: 0.85rem;
    color: var(--text-secondary);
    opacity: 0.7;
  }

  /* KPI Cards */
  .kpi-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 20px;
    margin: -40px auto 48px;
    position: relative;
    z-index: 10;
  }
  .kpi-card {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 28px 20px;
    text-align: center;
    box-shadow: 0 8px 32px rgba(0,0,0,0.3);
