  .kpi-value {
    font-size: 2.8rem;
    font-weight: 800;
    color: var(--gold);
    line-height: 1.1;
  }
  .kpi-label {
    font-size: 0.82rem;
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-top: 8px;
  }
  .kpi-detail {
    font-size: 0.8rem;
    color: var(--gold-light);
    margin-top: 6px;
    opacity: 0.85;
  }

  /* Sections */
  .section {
    margin-bottom: 56px;
  }
  .section-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 24px;
    padding-bottom: 12px;
    border-bottom: 2px solid var(--border);
