  .section-number {
    background: var(--gold);
    color: var(--bg-dark);
    font-weight: 800;
    font-size: 0.85rem;
    width: 32px;
    height: 32px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
  }
  .section-header h2 {
    font-size: 1.6rem;
    color: var(--gold);
    font-weight: 700;
  }
  .section p, .section li {
    color: var(--text-secondary);
    margin-bottom: 14px;
  }

  /* Top Composers Bar Chart Area */
  .chart-container {
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 32px;
    margin: 24px 0;
    box-shadow: 0 4px 20px rgba(0,0,0,0.2);
