  .ranking-table th {
    background: var(--bg-section);
    color: var(--gold);
    padding: 12px 16px;
    text-align: left;
    font-size: 0.8rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    border-bottom: 2px solid var(--gold-dark);
