    padding: 28px;
    box-shadow: 0 4px 20px rgba(0,0,0,0.2);
  }
  .era-card h3 {
    color: var(--gold);
    font-size: 1.15rem;
    margin-bottom: 6px;
  }
  .era-card .era-period {
    color: var(--text-secondary);
    font-size: 0.82rem;
    opacity: 0.7;
    margin-bottom: 14px;
  }
  .era-stat {
    display: flex;
    justify-content: space-between;
    padding: 6px 0;
    border-bottom: 1px solid rgba(255,255,255,0.04);
    font-size: 0.9rem;
    color: var(--text-secondary);
  }
  .era-stat strong {
    color: var(--gold-light);
  }
  .era-card .era-composers {
    margin-top: 12px;
    font-size: 0.88rem;
    color: var(--text-secondary);
  }
  .era-card .era-composers span {
    color: var(--gold-light);
    font-weight: 600;
  }

  /* Milestone Timeline */
  .timeline {
    position: relative;
    padding-left: 32px;
    margin: 24px 0;
  }
  .timeline::before {
    content: '';
    position: absolute;
    left: 8px;
    top: 0;
    bottom: 0;
    width: 2px;
    background: var(--border);
  }
  .timeline-item {
    position: relative;
    margin-bottom: 24px;
    padding: 16px 20px;
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 10px;
    box-shadow: 0 2px 12px rgba(0,0,0,0.15);
  }
  .timeline-item::before {
    content: '';
    position: absolute;
    left: -28px;
    top: 22px;
    width: 12px;
    height: 12px;
    border-radius: 50%;
    background: var(--gold);
    border: 2px solid var(--bg-dark);
  }
  .timeline-year {
    font-size: 0.78rem;
    color: var(--gold);
