  }
  .timeline-title {
    font-size: 1rem;
    color: var(--text-primary);
    margin: 4px 0;
    font-weight: 600;
  }
  .timeline-desc {
    font-size: 0.88rem;
    color: var(--text-secondary);
  }

  /* Takeaway boxes */
  .takeaway-list {
    list-style: none;
    counter-reset: takeaway;
    margin: 24px 0;
  }
  .takeaway-list li {
    counter-increment: takeaway;
    background: var(--bg-card);
    border: 1px solid var(--border);
