    margin-bottom: 16px;
    position: relative;
    box-shadow: 0 2px 12px rgba(0,0,0,0.15);
  }
  .takeaway-list li::before {
    content: counter(takeaway);
    position: absolute;
    left: 18px;
    top: 18px;
    background: var(--gold);
    color: var(--bg-dark);
    font-weight: 800;
    font-size: 0.85rem;
    width: 28px;
    height: 28px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  .takeaway-list li strong {
    color: var(--gold-light);
  }

  /* Decade Heatmap */
  .decade-table {
    width: 100%;
    border-collapse: collapse;
    margin: 20px 0;
  }
  .decade-table th {
    background: var(--bg-section);
