  /* Note callout */
  .note {
    background: rgba(197,164,78,0.08);
    border-left: 3px solid var(--gold);
    padding: 14px 18px;
    border-radius: 0 8px 8px 0;
    margin: 16px 0;
    font-size: 0.88rem;
    color: var(--text-secondary);
  }
  .note strong {
    color: var(--gold-light);
