  @media (max-width: 900px) {
    .kpi-grid { grid-template-columns: repeat(2, 1fr); }
    .era-grid { grid-template-columns: 1fr; }
    .hero h1 { font-size: 1.8rem; }
  }
  @media (max-width: 600px) {
    .kpi-grid { grid-template-columns: 1fr; }
  }
</style>
</head>
